// Те саме очищення, що й у Python-сервісі, але для n8n
const body = $input.first().json.body || {};
const pick = (...keys) => keys.map(k => body[k]).find(v => v) || '';

let digits = String(pick('phone', 'tel', 'your-phone')).replace(/\D/g, '');
if (digits.length === 10 && digits.startsWith('0')) digits = '38' + digits;
if (digits.length === 9) digits = '380' + digits;
const phone = digits.length === 12 && digits.startsWith('380') ? '+' + digits : null;

const pageUrl = pick('page_url', 'url', '_wpcf7_container_post_url');
const params = pageUrl.includes('?') ? new URLSearchParams(pageUrl.split('?')[1]) : new URLSearchParams();

return [{
  json: {
    name: pick('name', 'your-name') || 'Без імені',
    phone,
    rawPhone: pick('phone', 'tel', 'your-phone'),
    email: String(pick('email', 'your-email')).toLowerCase(),
    message: pick('message', 'your-message'),
    page: pageUrl.split('?')[0],
    utm_source: body.utm_source || params.get('utm_source') || '',
    utm_campaign: body.utm_campaign || params.get('utm_campaign') || '',
    receivedAt: new Date().toISOString(),
  }
}];
